class Solution {
    public int numMusicPlaylists(int n, int goal, int k) {
        long MOD = 1000000007;
        long[][] dp = new long[goal + 1][n + 1];
        dp[0][0] = 1;
        for (int i = 1; i <= goal; i++) {
            for (int j = 1; j <= n; j++) {
                dp[i][j] = (dp[i - 1][j - 1] * (n - j + 1)) % MOD;
                dp[i][j] = (dp[i][j] + dp[i - 1][j] * Math.max(j - k, 0)) % MOD;
            }
        }
        return (int) dp[goal][n];
    }
}

class Solution {
    public int numMusicPlaylists(int n, int goal, int k) {
        long MOD = 1000000007;
        long[] dp = new long[n + 1];
        dp[0] = 1;
        for (int i = 1; i <= goal; i++) {
            long[] ndp = new long[n + 1];
            for (int j = 1; j <= n; j++) {
                ndp[j] = (dp[j - 1] * (n - j + 1)) % MOD;
                ndp[j] = (ndp[j] + dp[j] * Math.max(j - k, 0)) % MOD;
            }
            dp = ndp;
        }
        return (int) dp[n];
    }
}
